/**
 * The resource namespaces the client exposes.
 *
 * The client extends this rather than listing the namespaces itself, so a
 * fragment whose last served operation lands or leaves cannot be forgotten
 * in the hand-written half.
 */
export abstract class GeneratedResources implements ResourceExecutor {
  abstract execute<T>(
    routeId: RouteId,
    bindings?: Readonly<Record<string, string>>,
    options?: ExecuteOptions,
  ): Promise<T>;

  /** The `api-keys` operations. */
  readonly apiKeys: ApiKeysClient = new ApiKeysClient(this);

  /** The `auth` operations. */
  readonly auth: AuthClient = new AuthClient(this);

  /** The `billing` operations. */
  readonly billing: BillingClient = new BillingClient(this);

  /** The `bootstrap` operations. */
  readonly bootstrap: BootstrapClient = new BootstrapClient(this);

  /** The `files` operations. */
  readonly files: FilesClient = new FilesClient(this);

  /** The `identity` operations. */
  readonly identity: IdentityClient = new IdentityClient(this);

  /** The `observations` operations. */
  readonly observations: ObservationsClient = new ObservationsClient(this);

  /** The `operations` operations. */
  readonly operations: OperationsClient = new OperationsClient(this);

  /** The `organizations` operations. */
  readonly organizations: OrganizationsClient = new OrganizationsClient(this);

  /** The `otlp` operations. */
  readonly otlp: OtlpClient = new OtlpClient(this);

  /** The `provider-credentials` operations. */
  readonly providerCredentials: ProviderCredentialsClient = new ProviderCredentialsClient(this);

  /** The `registry` operations. */
  readonly registry: RegistryClient = new RegistryClient(this);

  /** The `sessions` operations. */
  readonly sessions: SessionsClient = new SessionsClient(this);

  /** The `telemetry-lifecycle` operations. */
  readonly telemetryLifecycle: TelemetryLifecycleClient = new TelemetryLifecycleClient(this);

  /** The `uploads` operations. */
  readonly uploads: UploadsClient = new UploadsClient(this);

  /** The `usage` operations. */
  readonly usage: UsageClient = new UsageClient(this);

  /** The `workspace` operations. */
  readonly workspace: WorkspaceClient = new WorkspaceClient(this);

  /** The `workspaces` operations. */
  readonly workspaces: WorkspacesClient = new WorkspacesClient(this);
}
